open_result_file outputs/ct06_clock_tree.txt

# Get the clock port
set clk_port [get_ports clk]
if { [llength $clk_port] == 0 } {
    puts "Error: Clock port 'clk' not found"
    exit 1
}

# Get the net connected to the clock port
set clk_net_name [get_property [get_pins [lindex $clk_port 0]] NET]
set clk_net [get_nets $clk_net_name]

# Function to get all instances driven by a net
# Returns a list of instance names
proc get_drivers_by_net { net } {
    set pins [get_pins -of_objects $net -filter "DIRECTION == OUTPUT"]
    set instances {}
    foreach pin $pins {
        lappend instances [get_property $pin INSTANCE]
    }
    return $instances
}

# Function to check if an instance is a clock tree buffer
# We assume the CTS used BUF_X4 based on the prompt description "BUF_X4 buffers"
# However, to be safe, we might check if the cell is a buffer type.
# The prompt says "clock tree synthesized with ... BUF_X4 buffers".
# It's possible the root is CLKBUF. Let's look for standard cell buffers.
# We will collect all potential buffer instances in the clock tree hierarchy.

# Let's first collect all instances in the clock tree hierarchy
# We start from the clk net driver.
# We will use a queue to traverse the tree.

set queue [list $clk_net]
set visited_nets [dict create]
set buffers_info {} ;# List of {instance_name cell_name level}

# We need to distinguish between buffers and FFs.
# Buffers: cell_name is like BUF_X*, CLKBUF_X*
# FFs: cell_name is like FD*, etc. and pin is CK.

# Helper: Is it a buffer?
proc is_buffer { cell_name } {
    # Check if the cell name starts with BUF or CLKBUF
    if { [string match "BUF_*" $cell_name] || [string match "CLKBUF_*" $cell_name] } {
        return 1
    }
    return 0
}

# Helper: Is it a register clock pin?
proc is_ff_clock_pin { pin } {
    set inst [get_property $pin INSTANCE]
    set cell [get_property $inst CELL]
    # Standard cells for FFs usually start with FD, SR, etc.
    # We can also check if the pin direction is input and it's a clock pin.
    # But simpler: if it's not a buffer, and it's driven by the clock tree, it's likely a sink.
    # However, there might be buffers that drive other buffers.
    # The prompt asks for "register_sinks".
    # We need to count FFs.
    if { [string match "FD*" $cell] || [string match "SR*" $cell] || [string match "DF*" $cell] } {
        return 1
    }
    return 0
}

# Initialize level 1
# The driver of the clk_net is the root buffer(s)
set root_drivers [get_drivers_by_net $clk_net]
set level 1

# Process level 1
set current_level_buffers {}

foreach inst_name $root_drivers {
    set inst [get_cells $inst_name]
    set cell [get_property $inst CELL]

    if { [is_buffer $cell] } {
        lappend buffers_info "$inst_name $cell $level"
        lappend current_level_buffers $inst_name
    } else {
        # If the root driver is not a buffer, it might be the port itself or an inverter.
        # But CTS usually inserts a root buffer.
        # If it's an inverter, it's not a buffer in the context of the tree structure described.
        # The prompt says "BUF_X4 buffers".
        # If the driver is not a buffer, we skip it for the buffer list, but we need to traverse further.
        # However, if the root driver is not a buffer, the "Level 1" definition is tricky.
        # Let's assume the root driver IS a buffer as per CTS standard behavior.
        puts "Warning: Root driver $inst_name is not a buffer, cell $cell"
    }
}

# If no buffers were found at level 1, maybe the clk port drives a CLKBUF which is considered a buffer?
# My is_buffer check includes CLKBUF.

# Now traverse
# We need to keep track of visited nets to avoid cycles or re-processing
set processed_nets [dict create]

# Add root net to processed
dict set processed_nets $clk_net 1

while { [llength $current_level_buffers] > 0 } {
    set next_level_buffers {}
    set current_level [expr $level + 1]

    foreach inst_name $current_level_buffers {
        set inst [get_cells $inst_name]
        # Get the output pin(s) of this buffer
        set out_pins [get_pins -of_objects $inst -filter "DIRECTION == OUTPUT"]

        foreach out_pin $out_pins {
            set out_net [get_property $out_pin NET]

            # If net already processed, skip
            if { [dict exists $processed_nets $out_net] } {
                continue
            }
            dict set processed_nets $out_net 1

            # Get drivers of this net
            set drivers [get_drivers_by_net $out_net]

            set sink_count 0

            foreach driver_inst_name $drivers {
                set driver_inst [get_cells $driver_inst_name]
                set driver_cell [get_property $driver_inst CELL]

                if { [is_buffer $driver_cell] } {
                    # It's a child buffer
                    lappend buffers_info "$driver_inst_name $driver_cell $current_level"
                    lappend next_level_buffers $driver_inst_name
                } else {
                    # It's a sink (likely an FF)
                    # Check if it's an FF clock pin
                    # We need to check if the pin from the buffer connects to the CK pin of the FF
                    # The driver instance is the FF. The pin on the FF is the input pin connected to the buffer output.
                    set in_pins [get_pins -of_objects $driver_inst -filter "DIRECTION == INPUT"]
                    foreach in_pin $in_pins {
                        if { [get_property $in_pin NET] eq $out_net } {
                            # This is the pin driven by the buffer
                            if { [is_ff_clock_pin $in_pin] } {
                                incr sink_count
                            }
                        }
                    }
                }
            }

            # If the current buffer drove no other buffers and no FFs, it might be a leaf buffer with 0 sinks?
            # But we are iterating children. If a buffer has no children in the tree, it's a leaf.
            # The sink_count is for the *current* buffer (from the previous level iteration) driven by *its* output net.
            # Wait, the logic above counts sinks for the buffer `inst_name` from the previous level.
            # But we are inside the loop for `inst_name`.
            # The `sink_count` calculated here is for `inst_name`.
            # We need to append the sink count to the buffers_info entry for `inst_name`.
            # But `buffers_info` is a list of strings. We can't easily update it.
            # Better approach: Store buffer info in a dict keyed by instance name.
        }
    }

    incr level
    set current_level_buffers $next_level_buffers
}

# The previous approach of appending to a list is hard to update with sink counts.
# Let's restart with a dict.

set buffers_dict {}
set queue [list $clk_net]
set visited_nets [dict create]
dict set visited_nets $clk_net 1
set level 1

# Get root drivers
set root_drivers [get_drivers_by_net $clk_net]
set current_level_insts {}

foreach inst_name $root_drivers {
    set inst [get_cells $inst_name]
    set cell [get_property $inst CELL]
    if { [is_buffer $cell] } {
        dict set buffers_dict $inst_name [list $cell $level 0]
        lappend current_level_insts $inst_name
    }
}

set level 1
while { [llength $current_level_insts] > 0 } {
    set next_level_insts {}
    set current_level [expr $level + 1]

    foreach inst_name $current_level_insts {
        set inst [get_cells $inst_name]
        set out_pins [get_pins -of_objects $inst -filter "DIRECTION == OUTPUT"]

        foreach out_pin $out_pins {
            set out_net [get_property $out_pin NET]

            if { [dict exists $visited_nets $out_net] } {
                continue
            }
            dict set visited_nets $out_net 1

            set drivers [get_drivers_by_net $out_net]
            set sink_count 0

            foreach driver_inst_name $drivers {
                set driver_inst [get_cells $driver_inst_name]
                set driver_cell [get_property $driver_inst CELL]

                if { [is_buffer $driver_cell] } {
                    dict set buffers_dict $driver_inst_name [list $driver_cell $current_level 0]
                    lappend next_level_insts $driver_inst_name
                } else {
                    # Check if it's an FF clock pin
                    set in_pins [get_pins -of_objects $driver_inst -filter "DIRECTION == INPUT"]
                    foreach in_pin $in_pins {
                        if { [get_property $in_pin NET] eq $out_net } {
                            if { [is_ff_clock_pin $in_pin] } {
                                incr sink_count
                            }
                        }
                    }
                }
            }

            # Update sink count for the current buffer
            set current_info [dict get $buffers_dict $inst_name]
            dict set buffers_dict $inst_name [lindex $current_info 0] [lindex $current_info 1] $sink_count
        }
    }

    incr level
    set current_level_insts $next_level_insts
}

# Write to file
set fp [open outputs/ct06_clock_tree.txt w]
foreach inst_name [lsort [dict keys $buffers_dict]] {
    set info [dict get $buffers_dict $inst_name]
    set cell [lindex $info 0]
    set lvl [lindex $info 1]
    set sinks [lindex $info 2]
    puts $fp "$inst_name $cell $lvl $sinks"
}
close $fp

puts "Clock tree description written to outputs/ct06_clock_tree.txt"

