    close $fp
    exit 1
}

set clk_port [lindex $clk_ports 0]

# Find the net connected to the port
# One way is to get the pins of the top instance that are connected to this port
# The top instance name is usually the design name, which is 'gcd'
set top_inst [get_cells -quiet [current_design]]
if { $top_inst eq "" } {
    puts "Error: Could not determine top instance"
    close $fp
    exit 1
}

# Get pins of the top instance connected to the clk port
# We can use get_pins with -of_objects top_inst and filter by the port
# However, get_pins doesn't directly filter by port.
# Instead, we can get all pins of the top instance and check their NET property
# or use get_nets with a filter if we know the net name.

# A better approach: get the net by finding the pin on the top instance that is connected to the port.
# We can get the port's associated pins using get_pins -of_objects [get_ports clk]
# But ports don't have pins directly.

# Let's try to get the net by looking at the pins of the top module.
# We can get all pins of the top instance and find the one that is connected to the clk port.
# The port name is 'clk'. The pin name on the top instance is usually the same as the port name.
set clk_pin_name [get_property $clk_port NAME]

# Get the pin on the top instance with the same name as the port
set clk_inst_pin [get_pins -of_objects $top_inst ${clk_pin_name}]
if { [llength $clk_inst_pin] == 0 } {
    # If the pin name is not exactly the port name, try to find any input pin connected to the clk port
    # This is tricky. Let's assume the pin name matches the port name.
    puts "Warning: Pin ${clk_pin_name} not found on top instance"
    # Fallback: try to get nets connected to the port by other means
    # In OpenROAD, we can often get the net by getting the pins of the port if it exists in the DB
    # But in STA, ports are abstract.

    # Let's try to get all nets and find the one connected to the port
    # This is inefficient but robust.
    set all_nets [get_nets]
    set clk_net ""
    foreach net $all_nets {
        # Check if this net is connected to the port
        # We can check if the port is a member of the net
        set net_ports [get_ports -of_objects $net]
        if { [lsearch $net_ports $clk_port] >= 0 } {
            set clk_net $net
            break
        }
    }
} else {
    set clk_inst_pin [lindex $clk_inst_pin 0]
    set clk_net [get_property $clk_inst_pin NET]
}

if { $clk_net eq "" || $clk_net eq "NULL" } {
    puts "Error: Could not find clock net for port 'clk'"
    close $fp
    exit 1
}

