set buffers_dict {}

# Get the driver of the clk net (Level 1)
# The driver is a pin with direction OUTPUT connected to the clk_net
set clk_net_drivers [get_pins -of_objects $clk_net -filter "DIRECTION == OUTPUT"]
set level 1
set current_level_insts {}

foreach clk_driver_pin $clk_net_drivers {
