close $fp
puts "Clock tree description written to $output_file"

# Define the list of req_msg pins
set req_msg_pins {}
for {set i 0} {$i < 32} {incr i} {
    lappend req_msg_pins "req_msg[$i]"
}

# Constrain req_msg pins to the bottom edge and request ordering
# The -order flag in set_io_pin_constraint ensures they are placed in the order provided
set_io_pin_constraint -pin_names $req_msg_pins -region bottom:* -order

# Get all IO ports to identify remaining pins
set all_ports [get_ports *]
set remaining_pins {}
foreach port $all_ports {
    set port_name [get_property $port NAME]
    if {$port_name ni $req_msg_pins} {
        lappend remaining_pins $port_name
    }
}

# Constrain remaining pins to the entire boundary
# The platform defaults will handle layer assignment based on edge (metal3 for L/R, metal2 for T/B)
if {[llength $remaining_pins] > 0} {
    # We can constrain them to specific edges or let the placer decide.
    # The task says "remaining pins may be placed anywhere on the boundary".
    # Using -region * might be invalid syntax as seen in the warning.
    # Instead, we can assign them to specific edges or just leave them unconstrained 
    # if the default behavior places them. However, set_io_pin_constraint is needed to 
    # tell the placer about them if they aren't automatically picked up.
    # A safe way is to assign them to the top/left/right edges if they are not on bottom.
    # But since the task allows them anywhere, we can just constrain them to the whole boundary 
    # by using multiple regions or simply relying on the fact that place_pins places all 
    # unconstrained IO pins if they are in the design.

