# Helper procedure to get HPWL
proc get_hpwl_value {} {
    set result ""
    # Try report_hpwl command
    if {[catch {
        with_output_to_variable result {report_hpwl}
    }]} {
        # If report_hpwl fails, try report_metrics
        if {[catch {
            with_output_to_variable result {report_metrics}
        }]} {
            return "0.00"
        }
    }

    # Parse the result to find HPWL
    # report_hpwl usually outputs something like "Total HPWL: 12345.67"
    # report_metrics might have a different format
    if {[regexp -all -line {\[Hh][Pp][Ww][Ll].*([0-9]+\.[0-9]+)} $result match hpwl]} {
        return $hpwl
    } elseif {[regexp -all -line {hpwl.*([0-9]+\.[0-9]+)} $result match hpwl]} {
        return $hpwl
    } else {
        # Fallback: if the whole result is a number
        if {[regexp -line {^[0-9]+\.[0-9]+$} $result match hpwl]} {
            return $hpwl
        }
    }
    return "0.00"
}

