        if {[regexp -line {[0-9]+\.[0-9]+} $hpwl_str hpwl_val]} {
            return $hpwl_val
        }
    }

    # Fallback: if the whole string is a number
    if {[regexp -line {^[0-9]+\.[0-9]+$} $hpwl_str hpwl_val]} {
        return $hpwl_val
    }

    return 0.0
