if {[llength $clk_port] == 0} {
    puts "Error: Clock port 'clk' not found."
    exit 1
}
set clk_net [get_nets -of_objects $clk_port]
if {[llength $clk_net] == 0} {
    puts "Error: Clock net for 'clk' not found."
    exit 1
}
set clk_net_name [get_property name $clk_net]

# 2. Find all clock tree buffers
# The design state says BUF_X4 buffers are used.
# We will find all instances of BUF_X4.
set cts_buffers [get_cells -hierarchical -filter "REF_NAME eq BUF_X4"]

if {[llength $cts_buffers] == 0} {
    puts "Warning: No BUF_X4 buffers found. Trying CLKBUF_X3 or other common CTS buffers."
    # Fallback: try CLKBUF_X3
    set cts_buffers [get_cells -hierarchical -filter "REF_NAME eq CLKBUF_X3"]
}

if {[llength $cts_buffers] == 0} {
    puts "Error: No standard CTS buffers found."
    exit 1
}

# 3. Identify the root buffer(s)
# Root buffers are driven directly by the clock port/net.
set root_buffers [list]
foreach buf $cts_buffers {
    set input_pins [get_pins -of_objects $buf -filter "direction==in"]
    foreach pin $input_pins {
        set pin_net [get_nets -of_objects $pin]
        if {[llength $pin_net] > 0} {
            set net_name [get_property name [lindex $pin_net 0]]
            if {$net_name eq $clk_net_name} {
                lappend root_buffers $buf
            }
        }
    }
}

if {[llength $root_buffers] == 0} {
    puts "Error: No root buffers found driven by clk."
    exit 1
}

# 4. BFS to determine levels and sink counts
# Data structures:
# - level_map: assoc array instance_name -> level
# - sink_count_map: assoc array instance_name -> count
# - visited: set of visited buffers

set level_map [dict create]
set sink_count_map [dict create]
set visited [dict create]

# Queue for BFS: list of {buffer_instance_name level}
set queue [list]

# Initialize root buffers
foreach buf $root_buffers {
    dict set level_map $buf 1
    dict set visited $buf 1
    lappend queue [list $buf 1]
}

# Process queue
while {[llength $queue] > 0} {
    # Dequeue
    set current_pair [lindex $queue 0]
    set queue [lrange $queue 1 end]

    set current_buf [lindex $current_pair 0]
    set current_level [lindex $current_pair 1]

    # Get the output pin of the buffer
    # Buffers usually have a single output pin 'Y' or 'Z'. 
    # Let's find the output pin.
    set output_pins [get_pins -of_objects $current_buf -filter "direction==out"]

    if {[llength $output_pins] == 0} {
        continue
    }

    set out_pin [lindex $output_pins 0]
    set out_net [get_nets -of_objects $out_pin]

    if {[llength $out_net] == 0} {
        continue
    }

    set out_net_obj [lindex $out_net 0]
    set out_net_name [get_property name $out_net_obj]

    # Find all pins connected to this output net
    # We need to find:
    # 1. Other buffer input pins (next level)
    # 2. FF clock input pins (sinks)

    set connected_pins [get_pins -of_objects $out_net_obj]

    set next_level_buffers [list]
    set sink_count 0

    foreach pin $connected_pins {
        set pin_parent [get_property PARENT $pin]
        set pin_dir [get_property DIRECTION $pin]

        # Skip the buffer's own output pin
        if {$pin eq $out_pin} {
            continue
        }

        # Check if this pin belongs to a CTS buffer
        set parent_cell_type [get_property REF_NAME $pin_parent]

        if {$parent_cell_type in [list "BUF_X4" "CLKBUF_X3"]} {
            # It's another buffer in the clock tree
            if {![dict exists $visited $pin_parent]} {
                dict set visited $pin_parent 1
                set next_level [$current_level + 1]
                dict set level_map $pin_parent $next_level
                lappend next_level_buffers $pin_parent
            }
        } else {
            # It's likely a FF or other logic.
            # Check if it's a clock input to a sequential cell.
            # We can check if the pin is a clock pin or if the parent is a FF.
            # A simple heuristic: if it's not a buffer input, and it's connected to the clock net, it's a sink.
            # More robust: check if the pin is a clock pin.
            if {[get_property IS_CLOCK $pin] == "1"} {
                incr sink_count
            }
        }
    }

    # Store sink count for the current buffer
    dict set sink_count_map $current_buf $sink_count

    # Enqueue next level buffers
    foreach next_buf $next_level_buffers {
        lappend queue [list $next_buf $current_level]
    }
}

# 5. Write the output file
# Format: <instance_name> <cell_name> <level> <register_sinks>
# List every clock-tree buffer exactly once.

# Get all CTS buffers again to ensure we list all of them, even if disconnected (though unlikely in a valid CTS)
# We iterate over the level_map keys to get all visited buffers.
# If there are buffers not visited (disconnected), we should still list them? 
# The task says "List every clock-tree buffer". 
# Let's iterate over all identified CTS buffers.

foreach buf [lsort $cts_buffers] {
    if {[dict exists $level_map $buf]} {
        set level [dict get $level_map $buf]
        set sinks [dict get $sink_count_map $buf]
        set cell_name [get_property REF_NAME $buf]
        set buf_name [get_property NAME $buf]

        puts $fd "$buf_name $cell_name $level $sinks"
    } else {
        # Buffer not reached in BFS. 
        # This might happen if it's disconnected or an error.
        # We still need to list it. Assume level 0 or unreachable?
        # The task implies a valid tree. 
        # Let's assume level 0 if not visited.
        set cell_name [get_property REF_NAME $buf]
        set buf_name [get_property NAME $buf]
        puts $fd "$buf_name $cell_name 0 0"
    }
}

close $fd

puts "Clock tree description written to $outfile"

