# Get all IO ports
set all_ports [get_ports -of_objects [current_design]]

# Define req_msg pins explicitly
set req_msg_pins {}
for {set i 0} {$i < 32} {incr i} {
    lappend req_msg_pins "req_msg[$i]"
}

# Set constraint for req_msg pins: bottom edge, grouped, ordered
set_io_pin_constraint -pin_names $req_msg_pins -region bottom:* -group -order

# Identify remaining pins
set remaining_pins {}
foreach port $all_ports {
    set port_name [get_name $port]
    if {$port_name ni $req_msg_pins} {
        lappend remaining_pins $port_name
    }
}

# Distribute remaining pins to Left, Right, and Top edges
# The task allows them anywhere on the boundary.
# We'll split them between Left and Right for simplicity.
set left_pins {}
set right_pins {}
set num_remaining [llength $remaining_pins]
set half [expr {$num_remaining / 2}]

set i 0
foreach pin $remaining_pins {
    if {$i < $half} {
        lappend left_pins $pin
    } else {
        lappend right_pins $pin
    }
    incr i
}

# Set constraints for Left pins
if {[llength $left_pins] > 0} {
    set_io_pin_constraint -pin_names $left_pins -region left:*
}

# Set constraints for Right pins
if {[llength $right_pins] > 0} {
    set_io_pin_constraint -pin_names $right_pins -region right:*
}

# Place pins
# Metal3 for Left/Right (Horizontal pins), Metal2 for Top/Bottom (Vertical pins)
# The task specifies: metal3 for left/right, metal2 for top/bottom.
place_pins -hor_layers metal3 -ver_layers metal2

# Open the output file
set output_file "outputs/io_ports.txt"
file delete -force $output_file
set fp [open $output_file w]

# Get the top module name to strip from pin names
set top_name [current_design]

# Get all top-level ports
set ports [get_ports]

foreach port $ports {
    # Get the direction of the port
    set direction [get_property $port direction]

    # Handle potential missing direction (should not happen for IO ports)
    if { $direction == "" } {
        set direction "unknown"
    }

    # Get the pins associated with this port
    set pins [get_pins -of_objects $port]

    # If there is only one pin, it's a single-bit port
    if { [llength $pins] == 1 } {
        set port_name [get_property $port name]
        puts $fp "$port_name $direction"
    } else {
        # It's a multi-bit bus. List each bit.
        # The pin names are typically like "top_module/port_name[bit]"
        # We need to output "port_name[bit] direction"
        foreach pin $pins {
            set pin_name [get_property $pin name]
            # Strip the top module name from the pin name
            # The pin name is usually "${top_name}/${port_base}[bit]"
