    set pre [dict get $pre_locs $inst]
    set x_pre [lindex $pre 0]
    set y_pre [lindex $pre 1]

    set x_post [get_property $inst LOC_X]
    set y_post [get_property $inst LOC_Y]

    set dx [expr {$x_post - $x_pre}]
    set dy [expr {$y_post - $y_pre}]

    # Manhattan distance
    set disp [expr {abs($dx) + abs($dy)}]

    dict set displacements $inst $disp

    if {$disp > $max_disp} {
        set max_disp $disp
    }
    set total_disp [expr {$total_disp + $disp}]
}

