# A buffer is driven by clk_net if its input pin is connected to clk_net
set level1_bufs [get_cells -hierarchical * -filter {CELL_NAME == "BUF_X4"}]
set level1_bufs [lsearch -all -inline -regexp $level1_bufs {.*}]

# Filter level1_bufs to only those connected to clk_net
