    if {$cell_name == "BUF_X4"} {
        lappend all_bufs $inst
    }
}

# Identify the clock root net
set clk_port [get_ports clk]
if {$clk_port eq ""} {
    puts "Error: Clock port clk not found"
    exit 1
}

# Get the net connected to the port
set clk_net [get_property $clk_port NET]
if {$clk_net eq ""} {
    # Try to get nets connected to the port
    set clk_nets [get_nets -of_objects $clk_port]
    if {[llength $clk_nets] > 0} {
        set clk_net [lindex $clk_nets 0]
    } else {
        puts "Error: Cannot find net connected to clk port"
        exit 1
    }
}

# Find Level 1 buffers: those driven by clk_net
set actual_level1_bufs {}
foreach inst $all_bufs {
    set inst_pins [get_pins -of_objects $inst]
    foreach pin $inst_pins {
        set pin_net [get_property $pin NET]
        if {$pin_net eq $clk_net} {
            lappend actual_level1_bufs $inst
            break
        }
    }
}

# BFS to assign levels
set buffer_levels [dict create]
set queue {}

foreach inst $actual_level1_bufs {
    dict set buffer_levels $inst 1
    lappend queue [list $inst 1]
}

while {[llength $queue] > 0} {
    set current [lindex $queue 0]
    set queue [lrange $queue 1 end]

    set inst [lindex $current 0]
    set level [lindex $current 1]
    set next_level [expr {$level + 1}]

    # Get output pin of the buffer
    set out_pin [get_pins -of_objects $inst -filter "PINTYPE == OUT"]
    if {$out_pin eq ""} {
        set out_pin [get_pins -of_objects $inst -filter "DIRECTION == OUT"]
    }

    if {$out_pin eq ""} {
        continue
    }

    set out_net [get_property $out_pin NET]

    # Find all BUF_X4 buffers whose input pin is connected to out_net
    foreach conn_inst $all_bufs {
        if {![dict exists $buffer_levels $conn_inst]} {
            set conn_pins [get_pins -of_objects $conn_inst]
            foreach conn_pin $conn_pins {
                set conn_pin_net [get_property $conn_pin NET]
                if {$conn_pin_net eq $out_net} {
                    dict set buffer_levels $conn_inst $next_level
                    lappend queue [list $conn_inst $next_level]
                    break
                }
            }
        }
    }
}

# For each buffer, count the number of flop clock pins driven by its output net
set sorted_buffers [lsort [dict keys $buffer_levels]]

foreach inst $sorted_buffers {
    set level [dict get $buffer_levels $inst]

    # Get output pin
    set out_pin [get_pins -of_objects $inst -filter "PINTYPE == OUT"]
    if {$out_pin eq ""} {
        set out_pin [get_pins -of_objects $inst -filter "DIRECTION == OUT"]
    }

    if {$out_pin eq ""} {
        set sink_count 0
    } else {
        set out_net [get_property $out_pin NET]

        # Get all pins connected to this net
        set all_pins_on_net [get_pins -of_objects [get_nets $out_net]]

        set sink_count 0
        foreach pin $all_pins_on_net {
            set cell_name [get_property $pin CELL]
            # Check if it's a flop
            if {[get_property $cell_name IS_FLOP] == "1"} {
                # Check if it's a clock pin
                set pin_type [get_property $pin PINTYPE]
                if {$pin_type == "CLK"} {
                    incr sink_count
                }
            }
        }
    }

    set cell_name [get_property $inst CELL]
    puts $outfile "$inst $cell_name $level $sink_count"
}

close $outfile

# Open the output file
set output_file "outputs/io_ports.txt"
set fid [open $output_file w]

# Get all top-level ports using a wildcard pattern
set ports [get_ports *]

# Check if any ports were found
if {[llength $ports] == 0} {
    puts "No ports found."
} else {
    # Iterate through each port
    foreach port $ports {
        # Get the port name
        set port_name [get_name $port]

        # Get the port direction
        set direction [get_property -object_type port direction $port]

        # Check if the port name indicates a bus (contains [ and ])
        if {[string match "*[*" $port_name] && [string match "*]" $port_name]} {
            # It's a bus, we need to expand it.
            # Check if it's a range (contains :)
            if {[string match "*:*" $port_name]} {
                # It's a range, e.g., req_msg[15:0]
                # Extract base name and range
                set bracket_start [string first "[" $port_name]
                set base_name [string range $port_name 0 [expr $bracket_start - 1]]
                set range_part [string range $port_name [expr $bracket_start + 1] end]
                # Remove the closing bracket
                set range_part [string trimright $range_part "]"]

                # Split by colon
                set range_list [split $range_part ":"]
                set high [lindex $range_list 0]
                set low [lindex $range_list 1]

                # Iterate from low to high
                for {set i $low} {$i <= $high} {incr i} {
                    puts $fid "${base_name}[${i}] $direction"
                }
            } else {
                # It's a single bit in the name, e.g., req_msg[14]
                # This might be a bus port that is already split, or a single-bit port with brackets in name?
                # If it's a bus port and get_ports returned it as one object with name "req_msg[14]",
                # then it's a single bit. But the task says "Multi-bit (bus) ports must be listed bit by bit".
                # If get_ports returns the whole bus, the name would be "req_msg[15:0]".
                # If it returns individual bits, the name would be "req_msg[14]".
                # In the latter case, we just list it.
                puts $fid "$port_name $direction"
            }
        } else {
            # Single-bit port
            puts $fid "$port_name $direction"
        }
    }
}

# Close the output file
close $fid

