    set drivers [get_fanin -to $pin -only_cells]

    foreach driver_inst $drivers {
        # Increment count for this driver instance
        if {[dict exists $driver_counts $driver_inst]} {
            set current_count [dict get $driver_counts $driver_inst]
            dict set driver_counts $driver_inst [expr {$current_count + 1}]
        } else {
            dict set driver_counts $driver_inst 1
        }
    }
}

# Write outputs/flop_clock_drivers.txt
set driver_file [open "outputs/flop_clock_drivers.txt" w]
foreach {inst count} [dict sorted $driver_counts] {
    puts $driver_file "$inst $count"
}
close $driver_file

# Ensure the outputs directory exists
if {![file exists outputs]} {
    file mkdir outputs
}

# 1. Analyze Flip-Flops
# Get all register instances (flip-flops and latches).
set ff_instances [all_registers -cells]

# Create an associative array to count cell types
set ff_cell_counts [dict create]
set total_ff 0

foreach inst $ff_instances {
    # Get the cell type of the instance
    # Use get_cells with -quiet to avoid warnings, and check if it returns a valid object
    set cell_obj [get_cells $inst]
    if {[llength $cell_obj] > 0} {
        set cell_type [get_property $cell_obj library_cell_name]
        if {$cell_type ne ""} {
            # Increment count
            if {[dict exists $ff_cell_counts $cell_type]} {
                set current_count [dict get $ff_cell_counts $cell_type]
                dict set ff_cell_counts $cell_type [expr {$current_count + 1}]
            } else {
                dict set ff_cell_counts $cell_type 1
            }
            incr total_ff
        }
    }
}

# Write outputs/flop_types.txt
set ff_types_file [open "outputs/flop_types.txt" w]
# Sort the keys manually
set sorted_keys [lsort [dict keys $ff_cell_counts]]
foreach cell_type $sorted_keys {
    set count [dict get $ff_cell_counts $cell_type]
    puts $ff_types_file "$cell_type $count"
}
puts $ff_types_file "total $total_ff"
close $ff_types_file

# 2. Analyze Flip-Flop Clock Drivers
# Get the clock pins of all registers
set ff_clock_pins [all_registers -clock_pins]

# Create an associative array to count drivers
set driver_counts [dict create]

foreach pin $ff_clock_pins {
    # Get the fanin to this pin to find the driver
    # -only_cells returns the instances driving the pin
    set drivers [get_fanin -to $pin -only_cells]

    foreach driver_inst $drivers {
        # Increment count for this driver instance
        if {[dict exists $driver_counts $driver_inst]} {
            set current_count [dict get $driver_counts $driver_inst]
            dict set driver_counts $driver_inst [expr {$current_count + 1}]
        } else {
            dict set driver_counts $driver_inst 1
        }
    }
}

# Write outputs/flop_clock_drivers.txt
set driver_file [open "outputs/flop_clock_drivers.txt" w]
# Sort the keys manually
set sorted_driver_keys [lsort [dict keys $driver_counts]]
foreach inst $sorted_driver_keys {
    set count [dict get $driver_counts $inst]
    puts $driver_file "$inst $count"
}
close $driver_file

# Run global routing
global_route -allow_congestion

# Report global routing wirelength
# The -net * flag is required to specify all nets
set report_output [report_wire_length -net * -global_route]

# Parse the total wirelength from the output.
# The output format typically includes a line like:
# [INFO GRT-0018] Total wirelength: 10598 um
set total_wirelength ""
foreach line [split $report_output "\n"] {
    if {[string match "*Total wirelength:*" $line]} {
        # Extract the number after "Total wirelength:" and before "um"
        if {[regexp {Total wirelength:\s+(\d+(?:\.\d+)?)\s+um} $line match total_wirelength]} {
            break
        }
    }
}

# If parsing from stdout failed, try writing to a file and reading it back
if {$total_wirelength eq ""} {
    set temp_report_file "outputs/temp_grt_report.txt"
    report_wire_length -net * -global_route -file $temp_report_file

    set fp [open $temp_report_file r]
    set content [read $fp]
    close $fp
    file delete $temp_report_file

    set total_wirelength ""
    foreach line [split $content "\n"] {
        if {[string match "*Total wirelength:*" $line]} {
            if {[regexp {Total wirelength:\s+(\d+(?:\.\d+)?)\s+um} $line match total_wirelength]} {
                break
            }
        }
    }
}

# Write the final value to the requested output file
set out_file "outputs/grt_wirelength.txt"
set fp [open $out_file w]
puts $fp $total_wirelength
close $fp

# Get all clock nets
set clock_net_objs [sta::find_all_clk_nets]

# Extract net names
set clock_net_names {}
foreach net_obj $clock_net_objs {
    lappend clock_net_names [$net_obj getName]
}

# Report wirelength for clock nets using global routing
report_wire_length -net $clock_net_names -global_route -file outputs/clock_gr_wirelength.txt
